<?php
require_once __DIR__ . '/includes/visitor_portal.php';$pdo=db();$visitor=current_visitor($pdo);$status=$_GET['status']??'';$from=$_GET['from']??'';$to=$_GET['to']??'';$where=['vb.visitor_id=?'];$params=[$visitor['id']];if($status==='pending')$where[]='vb.request_status="Pending"';elseif($status==='approved')$where[]='vb.request_status IN ("Released","Ready for Release")';elseif($status==='returned')$where[]='vb.return_date IS NOT NULL OR vb.request_status="Returned"';elseif($status==='rejected')$where[]='vb.request_status="Rejected"';elseif($status==='overdue')$where[]='vb.return_date IS NULL AND vb.due_date<CURDATE()';if($from){$where[]='DATE(vb.borrow_date)>=?';$params[]=$from;}if($to){$where[]='DATE(vb.borrow_date)<=?';$params[]=$to;}$s=$pdo->prepare('SELECT vb.*,b.title,b.author FROM visitor_borrowing vb JOIN books b ON b.id=vb.book_id WHERE '.implode(' AND ',$where).' ORDER BY vb.borrow_date DESC');$s->execute($params);$rows=$s->fetchAll();visitor_portal_header('Borrowing History',$visitor);
?><h2>Borrowing History</h2><form class="row g-2 mb-3"><div class="col-md-3"><select name="status" class="form-select"><option value="">All statuses</option><?php foreach(['pending'=>'Pending','approved'=>'Approved / Released','returned'=>'Returned','rejected'=>'Rejected','overdue'=>'Overdue'] as $v=>$l):?><option value="<?=$v?>"<?=$status===$v?' selected':''?>><?=$l?></option><?php endforeach;?></select></div><div class="col-md-3"><input type="date" name="from" value="<?=e($from)?>" class="form-control"></div><div class="col-md-3"><input type="date" name="to" value="<?=e($to)?>" class="form-control"></div><div class="col-md-3"><button class="btn btn-success w-100">Filter</button></div></form><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Book</th><th>Borrowed</th><th>Due</th><th>Returned</th><th>Status</th><th>Receipt</th></tr></thead><tbody><?php foreach($rows as $row):$over=!$row['return_date']&&strtotime($row['due_date'])<strtotime('today');$st=$row['request_status']??'Pending';$stMap=['Pending'=>['warning text-dark','Pending Approval'],'Ready for Release'=>['info','Ready for Release'],'Released'=>['success','Released'],'Return Verification Pending'=>['info','Return Verification'],'Returned'=>['success','Returned'],'Rejected'=>['danger','Rejected']];[$class,$label]=$stMap[$st]??['secondary',ucwords(str_replace('_',' ',$st))];$receivable=in_array($st,['Released','Ready for Release','Returned'],true);?><tr><td><strong><?=e($row['title'])?></strong><div class="small text-muted"><?=e($row['author'])?></div><?php if(!empty($row['review_notes'])):?><div class="small text-muted"><em><?=e($row['review_notes'])?></em></div><?php endif;?></td><td><?=e($row['borrow_date'])?></td><td><?=e($row['due_date'])?></td><td><?=e($row['return_date']?:'—')?></td><td><span class="badge bg-<?=$class?>"><?=e($label)?></span></td><td><?php if($receivable):?><a class="btn btn-outline-success btn-sm" target="_blank" href="guest_receipt.php?id=<?=(int)$row['id']?>">View</a><?php else:?><span class="text-muted small">—</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-4">No matching history.</td></tr><?php endif;?></tbody></table></div></div><?php visitor_portal_footer(); ?>
